    async (payload) => {
      await api.post("/auth/register/", payload);
      // Backend ╨┐╤А╨╕ ╤А╨╡╨│╨╕╤Б╤В╤А╨░╤Ж╨╕╨╕ ╨╜╨╡ ╨▓╤Л╨┤╨░╤С╤В ╤В╨╛╨║╨╡╨╜╤Л тАФ ╨▓╤Е╨╛╨┤╨╕╨╝ ╤Б╤А╨░╨╖╤Г ╨┐╨╛╤Б╨╗╨╡ ╤Б╨╛╨╖╨┤╨░╨╜╨╕╤П.
      return login({ email: payload.email, password: payload.password });
    },
    [login],
  );

  const logout = useCallback(async () => {
    const refresh = tokenStorage.getRefresh();
    try {
      if (refresh) {
        await api.post("/auth/logout/", { refresh });
      }
    } catch {
      // ╨Ф╨░╨╢╨╡ ╨╡╤Б╨╗╨╕ backend ╨╜╨╡╨┤╨╛╤Б╤В╤Г╨┐╨╡╨╜, ╨╗╨╛╨║╨░╨╗╤М╨╜╤Г╤О ╤Б╨╡╤Б╤Б╨╕╤О ╨╖╨░╨║╤А╤Л╨▓╨░╨╡╨╝.
    } finally {
      clearSession();
    }
  }, [clearSession]);

  const value = useMemo(
    () => ({ user, initializing, login, register, logout }),
    [user, initializing, login, register, logout],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth ╨┤╨╛╨╗╨╢╨╡╨╜ ╨╕╤Б╨┐╨╛╨╗╤М╨╖╨╛╨▓╨░╤В╤М╤Б╤П ╨▓╨╜╤Г╤В╤А╨╕ AuthProvider");
  }
  return context;
}

/** ╨Я╨╛╨┤╨┐╨╕╤Б╨╕ ╤А╨╛╨╗╨╡╨╣ ╨┤╨╗╤П ╨╕╨╜╤В╨╡╤А╤Д╨╡╨╣╤Б╨░. */
export const ROLE_LABELS = {
  reader: "╨з╨╕╤В╨░╤В╨╡╨╗╤М",
  librarian: "╨С╨╕╨▒╨╗╨╕╨╛╤В╨╡╨║╨░╤А╤М",
  admin: "╨Р╨┤╨╝╨╕╨╜╨╕╤Б╤В╤А╨░╤В╨╛╤А",
};

export function getRoleLabel(role) {
  return ROLE_LABELS[role] || role || "тАФ";
}

import { Navigate, Outlet, useLocation } from "react-router-dom";

import Loader from "../components/Loader";
import { useAuth } from "./AuthContext";

/** ╨Я╤Г╤Б╨║╨░╨╡╤В ╤В╨╛╨╗╤М╨║╨╛ ╨░╨▓╤В╨╛╤А╨╕╨╖╨╛╨▓╨░╨╜╨╜╤Л╤Е; ╨╖╨░╨┐╨╛╨╝╨╕╨╜╨░╨╡╤В ╨░╨┤╤А╨╡╤Б, ╨║╤Г╨┤╨░ ╨┐╨╛╨╗╤М╨╖╨╛╨▓╨░╤В╨╡╨╗╤М ╤И╤С╨╗. */
export function ProtectedRoute() {
  const { user, initializing } = useAuth();
  const location = useLocation();

  if (initializing) {
    return <Loader full height="page" text="╨Я╤А╨╛╨▓╨╡╤А╤П╨╡╨╝ ╨░╨▓╤В╨╛╤А╨╕╨╖╨░╤Ж╨╕╤ОтАж" />;
  }

  if (!user) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  return <Outlet />;
}

/** ╨б╤В╤А╨░╨╜╨╕╤Ж╤Л ╨▓╤Е╨╛╨┤╨░ ╨╕ ╤А╨╡╨│╨╕╤Б╤В╤А╨░╤Ж╨╕╨╕: ╨░╨▓╤В╨╛╤А╨╕╨╖╨╛╨▓╨░╨╜╨╜╨╛╨╝╤Г ╨╖╨┤╨╡╤Б╤М ╨┤╨╡╨╗╨░╤В╤М ╨╜╨╡╤З╨╡╨│╨╛. */
export function PublicOnlyRoute() {
  const { user, initializing } = useAuth();

  if (initializing) {
    return <Loader full height="page" text="╨Я╤А╨╛╨▓╨╡╤А╤П╨╡╨╝ ╨░╨▓╤В╨╛╤А╨╕╨╖╨░╤Ж╨╕╤ОтАж" />;
  }

  if (user) {
    return <Navigate to="/" replace />;
  }

