  );
}

/** ╨б╨╛╨╛╨▒╤Й╨╡╨╜╨╕╨╡ ╨╛╨▒ ╨╛╤И╨╕╨▒╨║╨╡ ╤Б ╨╜╨╡╨╛╨▒╤П╨╖╨░╤В╨╡╨╗╤М╨╜╨╛╨╣ ╨║╨╜╨╛╨┐╨║╨╛╨╣ ╨┐╨╛╨▓╤В╨╛╤А╨░. */
export default function ErrorMessage({ message, onRetry, retryLabel = "╨Я╨╛╨▓╤В╨╛╤А╨╕╤В╤М" }) {
  if (!message) return null;

  return (
    <div className="alert alert--error" role="alert">
