          ╨Э╨╡╤В ╨░╨║╨║╨░╤Г╨╜╤В╨░?{" "}
          <Link className="link" to="/register">
            ╨Ч╨░╤А╨╡╨│╨╕╤Б╤В╤А╨╕╤А╨╛╨▓╨░╤В╤М╤Б╤П
          </Link>
        </span>
      }
    >
      <ErrorMessage message={generalError} />

      <form className="form" onSubmit={handleSubmit} noValidate>
        <div className="field">
          <label className="field__label" htmlFor="login-email">
            Email
          </label>
          <input
            id="login-email"
            className={`input${fieldErrors.email ? " input--invalid" : ""}`}
            type="email"
            name="email"
            autoComplete="email"
            placeholder="reader1@library.local"
            value={form.email}
            onChange={handleChange}
            disabled={submitting}
            aria-invalid={Boolean(fieldErrors.email)}
          />
          {fieldErrors.email && <p className="field__error">{fieldErrors.email}</p>}
        </div>

        <div className="field">
          <label className="field__label" htmlFor="login-password">
            ╨Я╨░╤А╨╛╨╗╤М
          </label>
          <input
            id="login-password"
            className={`input${fieldErrors.password ? " input--invalid" : ""}`}
            type="password"
            name="password"
            autoComplete="current-password"
            placeholder="тАвтАвтАвтАвтАвтАвтАвтАв"
            value={form.password}
            onChange={handleChange}
            disabled={submitting}
            aria-invalid={Boolean(fieldErrors.password)}
          />
          {fieldErrors.password && <p className="field__error">{fieldErrors.password}</p>}
        </div>

        {fieldErrors.non_field_errors && (
          <p className="field__error">{fieldErrors.non_field_errors}</p>
        )}

        <button className="button button--primary button--block" type="submit" disabled={submitting}>
          {submitting ? "╨Т╤Е╨╛╨┤тАж" : "╨Т╨╛╨╣╤В╨╕"}
        </button>
      </form>
    </AuthLayout>
  );
}

