  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 18px 40px rgba(31, 36, 48, 0.08);
  --font: "Segoe UI", "Inter", system-ui, -apple-system, sans-serif;
}

*,
*::before,
