class LoanCreateView(APIView):
    """╨б╨╛╨╖╨┤╨░╨╜╨╕╨╡ ╨▒╤А╨╛╨╜╨╕ ╤З╨╕╤В╨░╤В╨╡╨╗╨╡╨╝. ╨з╨╕╤В╨░╤В╨╡╨╗╤М ╨▒╨╡╤А╤С╤В╤Б╤П ╨╕╨╖ JWT."""

