}

/** ╨Ц╨░╨╜╤А╤Л ╨┤╨╗╤П ╨▓╤Л╨┐╨░╨┤╨░╤О╤Й╨╡╨│╨╛ ╤Д╨╕╨╗╤М╤В╤А╨░. */
export async function fetchGenres({ signal } = {}) {
