}

/** ╨и╨░╨┐╨║╨░ ╨░╨▓╤В╨╛╤А╨╕╨╖╨╛╨▓╨░╨╜╨╜╤Л╤Е ╤Б╤В╤А╨░╨╜╨╕╤Ж: ╨╜╨░╨▓╨╕╨│╨░╤Ж╨╕╤П ╨╕ ╨░╨║╨║╨░╤Г╨╜╤В. */
export default function SiteHeader() {
  const { user, logout } = useAuth();
