import { useEffect, useState } from "react";

/** ╨Ю╨▒╨╗╨╛╨╢╨║╨░ ╨║╨╜╨╕╨│╨╕ ╤Б ╨╖╨░╨┐╨░╤Б╨╜╤Л╨╝ ╨▓╨░╤А╨╕╨░╨╜╤В╨╛╨╝, ╨╡╤Б╨╗╨╕ ╨║╨░╤А╤В╨╕╨╜╨║╨░ ╨╜╨╡ ╨╖╨░╨│╤А╤Г╨╖╨╕╨╗╨░╤Б╤М. */
export default function BookCover({ book, large = false }) {
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    setFailed(false);
  }, [book.id, book.cover_url]);

  const className = `book-cover${large ? " book-cover--large" : ""}`;
  const letter = (book.title || "?").trim().charAt(0).toUpperCase() || "?";

  if (!book.cover_url || failed) {
    return (
      <div className={`${className} book-cover--fallback`} aria-hidden="true">
        <span className="book-cover__letter">{letter}</span>
      </div>
    );
  }

  return (
    <div className={className}>
      <img
        className="book-cover__image"
        src={book.cover_url}
        alt={`╨Ю╨▒╨╗╨╛╨╢╨║╨░ ╨║╨╜╨╕╨│╨╕ ┬л${book.title}┬╗`}
        loading="lazy"
        onError={() => setFailed(true)}
      />
    </div>
  );
}

/** ╨Ф╨╛╤Б╤В╤Г╨┐╨╜╨╛╤Б╤В╤М ╨║╨╜╨╕╨│╨╕: ╤Б╨║╨╛╨╗╤М╨║╨╛ ╤Н╨║╨╖╨╡╨╝╨┐╨╗╤П╤А╨╛╨▓ ╤Б╨▓╨╛╨▒╨╛╨┤╨╜╨╛. */
export default function AvailabilityBadge({ free, total }) {
  let modifier = "availability--free";
  let label = `╨б╨▓╨╛╨▒╨╛╨┤╨╜╨╛ ${free} ╨╕╨╖ ${total}`;

  if (!total) {
    modifier = "availability--none";
    label = "╨н╨║╨╖╨╡╨╝╨┐╨╗╤П╤А╨╛╨▓ ╨╜╨╡╤В";
  } else if (!free) {
    modifier = "availability--busy";
    label = "╨Э╨╡╤В ╤Б╨▓╨╛╨▒╨╛╨┤╨╜╤Л╤Е ╤Н╨║╨╖╨╡╨╝╨┐╨╗╤П╤А╨╛╨▓";
  }

  return (
    <span className={`availability ${modifier}`}>
      <span className="availability__dot" aria-hidden="true" />
      {label}
    </span>
  );
}

import { PAGE_SIZE } from "../api/books";

/** ╨Я╨╛╤Б╤В╤А╨░╨╜╨╕╤З╨╜╨░╤П ╨╜╨░╨▓╨╕╨│╨░╤Ж╨╕╤П ╨║╨░╤В╨░╨╗╨╛╨│╨░. */
export default function Pagination({ page, count, onChange }) {
  const totalPages = Math.max(1, Math.ceil(count / PAGE_SIZE));
  if (totalPages <= 1) return null;

  const pages = Array.from({ length: totalPages }, (_, index) => index + 1);

  return (
    <nav className="pagination" aria-label="╨б╤В╤А╨░╨╜╨╕╤Ж╤Л ╨║╨░╤В╨░╨╗╨╛╨│╨░">
      <button
        type="button"
        className="button button--ghost pagination__button"
        onClick={() => onChange(page - 1)}
        disabled={page <= 1}
      >
        ╨Э╨░╨╖╨░╨┤
      </button>

      <div className="pagination__pages">
        {pages.map((number) => (
          <button
            key={number}
            type="button"
            className={`pagination__page${number === page ? " pagination__page--active" : ""}`}
            onClick={() => onChange(number)}
            disabled={number === page}
            aria-current={number === page ? "page" : undefined}
          >
            {number}
          </button>
        ))}
      </div>

      <button
        type="button"
        className="button button--ghost pagination__button"
        onClick={() => onChange(page + 1)}
        disabled={page >= totalPages}
      >
        ╨Т╨┐╨╡╤А╤С╨┤
      </button>
    </nav>
  );
}

