import { useEffect, useState } from "react";
import { Link, useSearchParams } from "react-router-dom";

import { fetchBooks, fetchGenres } from "../api/books";
import { getErrorMessage } from "../api/client";
import AvailabilityBadge from "../components/AvailabilityBadge";
import BookCover from "../components/BookCover";
import ErrorMessage from "../components/ErrorMessage";
import Loader from "../components/Loader";
import Pagination from "../components/Pagination";
import SiteHeader from "../components/SiteHeader";
import "../styles/catalog.css";

function parsePage(raw) {
  const page = Number.parseInt(raw || "1", 10);
  return Number.isFinite(page) && page > 0 ? page : 1;
}

export default function CatalogPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const search = searchParams.get("search") || "";
  const genre = searchParams.get("genre") || "";
  const page = parsePage(searchParams.get("page"));

  const [searchInput, setSearchInput] = useState(search);
  const [genres, setGenres] = useState([]);
  const [books, setBooks] = useState([]);
  const [count, setCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [reloadKey, setReloadKey] = useState(0);

  // ╨Т╨╛╨╖╨▓╤А╨░╤В ╨┐╨╛ ╨╕╤Б╤В╨╛╤А╨╕╨╕ ╨▒╤А╨░╤Г╨╖╨╡╤А╨░ ╨┤╨╛╨╗╨╢╨╡╨╜ ╨╛╨▒╨╜╨╛╨▓╨╗╤П╤В╤М ╨┐╨╛╨╗╨╡ ╨┐╨╛╨╕╤Б╨║╨░.
  useEffect(() => {
    setSearchInput(search);
  }, [search]);

  useEffect(() => {
    const controller = new AbortController();
    let cancelled = false;

    fetchGenres({ signal: controller.signal })
      .then((items) => {
        if (!cancelled) setGenres(items);
      })
      .catch(() => {
        // ╨С╨╡╨╖ ╤Б╨┐╨╕╤Б╨║╨░ ╨╢╨░╨╜╤А╨╛╨▓ ╤Д╨╕╨╗╤М╤В╤А ╨╛╤Б╤В╨░╤С╤В╤Б╤П, ╨╜╨╛ ╨┐╤Г╤Б╤В╤Л╨╝ тАФ ╨║╨░╤В╨░╨╗╨╛╨│ ╤А╨░╨▒╨╛╤В╨░╨╡╤В.
      });

    return () => {
      cancelled = true;
      controller.abort();
    };
  }, []);

  useEffect(() => {
    const controller = new AbortController();
    let cancelled = false;

    setLoading(true);
    setError("");

    fetchBooks({ search, genre, page, signal: controller.signal })
      .then((data) => {
        if (cancelled) return;
        setBooks(data.results);
        setCount(data.count);
      })
      .catch((requestError) => {
        if (cancelled || controller.signal.aborted) return;
        setBooks([]);
        setCount(0);
        setError(
          getErrorMessage(requestError, "╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╨╖╨░╨│╤А╤Г╨╖╨╕╤В╤М ╨║╨░╤В╨░╨╗╨╛╨│. ╨Я╨╛╨┐╤А╨╛╨▒╤Г╨╣╤В╨╡ ╨╡╤Й╤С ╤А╨░╨╖."),
        );
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
      controller.abort();
    };
  }, [search, genre, page, reloadKey]);

  function updateFilters(patch) {
    const next = new URLSearchParams(searchParams);
    Object.entries(patch).forEach(([key, value]) => {
      if (value) next.set(key, value);
      else next.delete(key);
    });
    next.delete("page");
    setSearchParams(next);
  }

  function handleSearch(event) {
    event.preventDefault();
    updateFilters({ search: searchInput.trim() });
  }

  function handleGenre(event) {
    updateFilters({ genre: event.target.value });
  }

  function resetFilters() {
    setSearchInput("");
    setSearchParams({});
  }

  function goToPage(nextPage) {
    const next = new URLSearchParams(searchParams);
    if (nextPage <= 1) next.delete("page");
    else next.set("page", String(nextPage));
    setSearchParams(next);
  }

  const hasFilters = Boolean(search || genre);
  const isEmpty = !loading && !error && books.length === 0;

  return (
    <div className="page">
      <SiteHeader />

      <main className="catalog">
