import { useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";

import { fetchAvailability, fetchBook } from "../api/books";
import { getErrorMessage } from "../api/client";
import AvailabilityBadge from "../components/AvailabilityBadge";
import BookCover from "../components/BookCover";
import ErrorMessage from "../components/ErrorMessage";
import Loader from "../components/Loader";
import SiteHeader from "../components/SiteHeader";
import "../styles/book.css";

const DEFAULT_DAYS = 14;
const MAX_DAYS = 30;

const CONDITION_LABELS = {
  new: "╨Э╨╛╨▓╤Л╨╣",
  good: "╨е╨╛╤А╨╛╤И╨╕╨╣",
  worn: "╨Я╨╛╤В╤А╤С╨┐╨░╨╜╨╜╤Л╨╣",
};

function toISODate(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function todayISO() {
  return toISODate(new Date());
}

function addDays(isoDate, days) {
  const date = new Date(`${isoDate}T00:00:00`);
  date.setDate(date.getDate() + days);
  return toISODate(date);
}

function formatDate(isoDate) {
  if (!isoDate) return "";
  const [year, month, day] = isoDate.split("-");
  return `${day}.${month}.${year}`;
}

function validatePeriod(startDate, dueDate) {
  if (!startDate || !dueDate) return "╨г╨║╨░╨╢╨╕╤В╨╡ ╨╛╨▒╨╡ ╨┤╨░╤В╤Л";
  if (startDate < todayISO()) return "╨Ф╨░╤В╨░ ╨╜╨░╤З╨░╨╗╨░ ╨╜╨╡ ╨╝╨╛╨╢╨╡╤В ╨▒╤Л╤В╤М ╨▓ ╨┐╤А╨╛╤И╨╗╨╛╨╝";
  if (dueDate <= startDate) return "╨Ф╨░╤В╨░ ╨▓╨╛╨╖╨▓╤А╨░╤В╨░ ╨┤╨╛╨╗╨╢╨╜╨░ ╨▒╤Л╤В╤М ╨┐╨╛╨╖╨╢╨╡ ╨┤╨░╤В╤Л ╨╜╨░╤З╨░╨╗╨░";

  const days = (new Date(`${dueDate}T00:00:00`) - new Date(`${startDate}T00:00:00`)) /
    (24 * 60 * 60 * 1000);
  if (days > MAX_DAYS) return `╨Ь╨░╨║╤Б╨╕╨╝╨░╨╗╤М╨╜╤Л╨╣ ╤Б╤А╨╛╨║ тАФ ${MAX_DAYS} ╨┤╨╜╨╡╨╣`;
  return "";
}

function initialPeriod() {
  const startDate = todayISO();
  return { startDate, dueDate: addDays(startDate, DEFAULT_DAYS) };
}

export default function BookDetailPage() {
  const { id } = useParams();
  const [book, setBook] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [reloadKey, setReloadKey] = useState(0);

  const [period, setPeriod] = useState(initialPeriod);
  const [appliedPeriod, setAppliedPeriod] = useState(initialPeriod);
  const [dateError, setDateError] = useState("");
  const [availability, setAvailability] = useState(null);
  const [availabilityLoading, setAvailabilityLoading] = useState(true);
  const [availabilityError, setAvailabilityError] = useState("");
  const [availabilityReloadKey, setAvailabilityReloadKey] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    let cancelled = false;

    setLoading(true);
    setError("");

    fetchBook(id, { signal: controller.signal })
      .then((data) => {
        if (!cancelled) setBook(data);
      })
      .catch((requestError) => {
        if (cancelled || controller.signal.aborted) return;
        setBook(null);
        setError(
          getErrorMessage(requestError, "╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╨╖╨░╨│╤А╤Г╨╖╨╕╤В╤М ╨║╨╜╨╕╨│╤Г. ╨Я╨╛╨┐╤А╨╛╨▒╤Г╨╣╤В╨╡ ╨╡╤Й╤С ╤А╨░╨╖."),
        );
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
      controller.abort();
    };
  }, [id, reloadKey]);

  useEffect(() => {
    const controller = new AbortController();
    let cancelled = false;

    setAvailabilityLoading(true);
    setAvailabilityError("");

    fetchAvailability(id, { ...appliedPeriod, signal: controller.signal })
      .then((data) => {
        if (!cancelled) setAvailability(data);
      })
      .catch((requestError) => {
        if (cancelled || controller.signal.aborted) return;
        setAvailability(null);
        setAvailabilityError(
          getErrorMessage(requestError, "╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╨┐╤А╨╛╨▓╨╡╤А╨╕╤В╤М ╨┤╨╛╤Б╤В╤Г╨┐╨╜╨╛╤Б╤В╤М."),
        );
      })
      .finally(() => {
        if (!cancelled) setAvailabilityLoading(false);
      });

    return () => {
      cancelled = true;
      controller.abort();
    };
  }, [id, appliedPeriod, availabilityReloadKey]);

  function handleAvailabilitySubmit(event) {
    event.preventDefault();
    const problem = validatePeriod(period.startDate, period.dueDate);
    setDateError(problem);
    if (problem) return;
    setAppliedPeriod({ startDate: period.startDate, dueDate: period.dueDate });
  }

  function handleResetPeriod() {
    const next = initialPeriod();
    setPeriod(next);
    setAppliedPeriod({ ...next });
    setDateError("");
  }

  return (
    <div className="page">
      <SiteHeader />

      <main className="book-page">
        <Link className="book-page__back" to="/catalog">
