  check("╨Ъ╨░╤А╤В╨╛╤З╨║╨░ ╨┐╨╛╨║╨░╨╖╤Л╨▓╨░╨╡╤В ╨░╨▓╤В╨╛╤А╨░", searchAuthor === "╨б╤В╨░╨╜╨╕╤Б╨╗╨░╨▓ ╨Ы╨╡╨╝", searchAuthor);

