const CDP_PORT = 9222;
const APP = "http://localhost:5173";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  const targets = await (await fetch(`http://127.0.0.1:${CDP_PORT}/json/list`)).json();
  const page = targets.find((item) => item.type === "page");
  if (!page) throw new Error("no page target");

  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve) => ws.addEventListener("open", resolve, { once: true }));

  let lastId = 0;
  const pending = new Map();
  ws.addEventListener("message", (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) reject(new Error(JSON.stringify(message.error)));
      else resolve(message.result);
    }
  });

  function send(method, params = {}) {
    const id = ++lastId;
    ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
  }

  async function evalJs(expression) {
    const response = await send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true,
      userGesture: true,
    });
    if (response.exceptionDetails) {
      throw new Error(response.exceptionDetails.exception?.description || "evaluate failed");
    }
    return response.result.value;
  }

  await send("Page.enable");
  await send("Runtime.enable");
  await send("Storage.clearDataForOrigin", { origin: APP, storageTypes: "local_storage" });
  await send("Page.navigate", { url: `${APP}/login` });
  await sleep(2500);

  await evalJs(`
    (function () {
      function fill(selector, value) {
        const input = document.querySelector(selector);
        const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
        setter.call(input, value);
        input.dispatchEvent(new Event('input', { bubbles: true }));
      }
      fill('#login-email', 'reader1@library.local');
      fill('#login-password', 'demo12345');
      document.querySelector('form').requestSubmit();
    })()
  `);
  await sleep(2500);
  console.log("after login:", await evalJs("location.pathname + location.search"));

  await evalJs(`
    (function () {
      const input = document.querySelector('#catalog-search');
      const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
      setter.call(input, '1984');
      input.dispatchEvent(new Event('input', { bubbles: true }));
      document.querySelector('.catalog__filters').requestSubmit();
    })()
  `);
  await sleep(2000);
  console.log("after search:", await evalJs("location.pathname + location.search"));
  console.log("cards:", await evalJs("document.querySelectorAll('.book-card').length"));
  console.log("href:", await evalJs("document.querySelector('.book-card')?.getAttribute('href')"));
  console.log("summary:", await evalJs("document.querySelector('.catalog__summary')?.textContent"));

  await evalJs("document.querySelector('.book-card')?.click();");
  await sleep(2000);
  console.log("detail:", await evalJs("location.pathname"));
  console.log("back href:", await evalJs("document.querySelector('.book-page__back')?.getAttribute('href')"));
  console.log("history.state:", await evalJs("JSON.stringify(history.state)"));
  console.log(
    "react state keys:",
    await evalJs("JSON.stringify(Object.keys(window.history.state || {}))"),
  );

  ws.close();
}

main().catch((error) => {
  console.error("ERROR:", error.message);
  process.exit(1);
});

