import { useEffect, useState } from "react";
import { Link } from "react-router-dom";

import { getErrorMessage } from "../api/client";
import { fetchLoans, updateLoanStatus } from "../api/loans";
import ErrorMessage from "../components/ErrorMessage";
import Loader from "../components/Loader";
import Pagination from "../components/Pagination";
import SiteHeader from "../components/SiteHeader";
import StatusBadge from "../components/StatusBadge";
import { formatDate } from "../utils/dates";
import "../styles/dashboard.css";

const STATUS_TABS = [
  { value: "", label: "╨Т╤Б╨╡" },
  { value: "created", label: "╨Ч╨░╨▒╤А╨╛╨╜╨╕╤А╨╛╨▓╨░╨╜╤Л" },
  { value: "active", label: "╨Э╨░ ╤А╤Г╨║╨░╤Е" },
  { value: "returned", label: "╨Т╨╛╨╖╨▓╤А╨░╤Й╨╡╨╜╤Л" },
  { value: "cancelled", label: "╨Ю╤В╨╝╨╡╨╜╨╡╨╜╤Л" },
];

export default function MyLoansPage() {
  const [status, setStatus] = useState("");
  const [page, setPage] = useState(1);
  const [loans, setLoans] = useState([]);
  const [count, setCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [actionError, setActionError] = useState("");
  const [actionId, setActionId] = useState(null);
  const [reloadKey, setReloadKey] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    let cancelled = false;

    async function loadLoans() {
      setLoading(true);
      setError("");
      try {
        const data = await fetchLoans({
          status,
          page,
          signal: controller.signal,
        });
        if (cancelled) return;
        setLoans(data.results);
        setCount(data.count);
      } catch (requestError) {
        if (cancelled || controller.signal.aborted) return;
        setLoans([]);
        setCount(0);
        setError(
          getErrorMessage(requestError, "╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╨╖╨░╨│╤А╤Г╨╖╨╕╤В╤М ╨▒╤А╨╛╨╜╨╕. ╨Я╨╛╨┐╤А╨╛╨▒╤Г╨╣╤В╨╡ ╨╡╤Й╤С ╤А╨░╨╖."),
        );
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    loadLoans();

    return () => {
      cancelled = true;
      controller.abort();
    };
  }, [status, page, reloadKey]);

  function changeStatus(value) {
    setStatus(value);
    setPage(1);
    setActionError("");
  }

  async function cancelLoan(loan) {
    if (!window.confirm(`╨Ю╤В╨╝╨╡╨╜╨╕╤В╤М ╨▒╤А╨╛╨╜╤М ┬л${loan.book.title}┬╗?`)) return;

    setActionId(loan.id);
    setActionError("");
    try {
      await updateLoanStatus(loan.id, "cancelled");
      if (loans.length === 1 && page > 1) setPage(page - 1);
      else setReloadKey((value) => value + 1);
    } catch (requestError) {
      setActionError(
        getErrorMessage(requestError, "╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╨╛╤В╨╝╨╡╨╜╨╕╤В╤М ╨▒╤А╨╛╨╜╤М. ╨Я╨╛╨┐╤А╨╛╨▒╤Г╨╣╤В╨╡ ╨╡╤Й╤С ╤А╨░╨╖."),
      );
    } finally {
      setActionId(null);
    }
  }

  const isEmpty = !loading && !error && loans.length === 0;

  return (
    <div className="page">
      <SiteHeader />

      <main className="dashboard">
        <div className="dashboard__head">
          <p className="dashboard__eyebrow">╨Ы╨╕╤З╨╜╤Л╨╣ ╨║╨░╨▒╨╕╨╜╨╡╤В</p>
          <h1 className="dashboard__title">╨Ь╨╛╨╕ ╨▒╤А╨╛╨╜╨╕</h1>
          <p className="dashboard__lead">
            ╨Ч╨┤╨╡╤Б╤М ╨▓╨╕╨┤╨╜╤Л ╨▓╨░╤И╨╕ ╨▒╤А╨╛╨╜╨╕ ╨╕ ╨▓╤Л╨┤╨░╤З╨╕. ╨С╤А╨╛╨╜╤М ╨╝╨╛╨╢╨╜╨╛ ╨╛╤В╨╝╨╡╨╜╨╕╤В╤М, ╨┐╨╛╨║╨░
            ╨▒╨╕╨▒╨╗╨╕╨╛╤В╨╡╨║╨░╤А╤М ╨╜╨╡ ╨▓╤Л╨┤╨░╨╗ ╨║╨╜╨╕╨│╤Г.
          </p>
        </div>

        <div className="dashboard__tabs" role="tablist" aria-label="╨б╤В╨░╤В╤Г╤Б╤Л ╨▒╤А╨╛╨╜╨╡╨╣">
          {STATUS_TABS.map((tab) => (
            <button
              key={tab.value || "all"}
              type="button"
              className={`dashboard__tab${
                status === tab.value ? " dashboard__tab--active" : ""
              }`}
              onClick={() => changeStatus(tab.value)}
