.dashboard {
  flex: 1;
  width: 100%;
  max-width: 1080px;
  margin: 0 auto;
  padding: 34px 28px 72px;
}

.dashboard__head {
  max-width: 720px;
}

.dashboard__eyebrow {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
}

.dashboard__title {
  margin-top: 8px;
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.dashboard__lead {
  margin-top: 8px;
  color: var(--ink-soft);
}

.dashboard__tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 24px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line);
}

.dashboard__tab {
  padding: 8px 14px;
  font-family: inherit;
  font-size: 14px;
  font-weight: 600;
  color: var(--ink-soft);
  background-color: transparent;
  border: 1px solid transparent;
  border-radius: 999px;
  cursor: pointer;
}

.dashboard__tab:hover {
  color: var(--accent-strong);
  background-color: var(--surface-muted);
}

.dashboard__tab--active {
  color: var(--accent-strong);
  background-color: var(--accent-soft);
  border-color: var(--accent-soft);
}

.dashboard__filters {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 14px;
  margin-top: 20px;
  padding: 16px 18px;
  background-color: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.dashboard__filters .field {
  flex: 0 1 260px;
}

.dashboard__summary {
  margin-top: 20px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.dashboard__success {
  margin-top: 16px;
  padding: 10px 14px;
  font-size: 14px;
  color: var(--accent-strong);
  background-color: var(--accent-soft);
  border-radius: var(--radius-sm);
}

.dashboard__empty {
  margin-top: 28px;
  padding: 40px 28px;
  text-align: center;
  background-color: var(--surface);
  border: 1px dashed var(--line);
  border-radius: var(--radius);
}

.dashboard__empty-title {
  font-size: 19px;
  font-weight: 700;
}

.dashboard__empty-text {
  margin: 8px auto 18px;
  max-width: 460px;
  color: var(--ink-soft);
}

.record-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-top: 14px;
}

.record-card {
  padding: 20px 22px;
  background-color: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 8px 20px rgba(31, 36, 48, 0.04);
}

.record-card__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.record-card__title {
  font-size: 18px;
  font-weight: 700;
  line-height: 1.3;
}

.record-card__author {
  margin-top: 2px;
  font-size: 14px;
  color: var(--ink-soft);
}

.record-card__details {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 12px 20px;
  margin-top: 16px;
}

.record-card__detail dt {
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.record-card__detail dd {
  margin-top: 3px;
  font-size: 14px;
}

.record-card__muted {
  display: block;
  font-size: 12.5px;
  color: var(--ink-soft);
}

.record-card__comment {
  margin-top: 14px;
  padding: 10px 12px;
  font-size: 13.5px;
  color: var(--ink-soft);
  background-color: var(--surface-muted);
  border-radius: var(--radius-sm);
}

.record-card__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 16px;
}

.queue-group {
  margin-top: 22px;
  padding: 18px 20px;
  background-color: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.queue-group__head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 10px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.queue-group__title {
  font-size: 17px;
  font-weight: 700;
}

.queue-group__author {
  font-size: 13.5px;
  color: var(--ink-soft);
}

.queue-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-top: 8px;
}

.queue-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px 16px;
  padding: 10px 0;
  border-bottom: 1px solid var(--line);
}

.queue-row:last-child {
  border-bottom: none;
}

.queue-row__reader {
  display: flex;
  flex-direction: column;
  min-width: 180px;
}

.queue-row__name {
  font-size: 14px;
  font-weight: 600;
}

.queue-row__email {
  font-size: 12.5px;
  color: var(--ink-soft);
}

.queue-row__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  font-size: 13px;
