const CDP_PORT = 9222;
const APP = "http://localhost:5173";
const API = "http://127.0.0.1:8000/api";
const PASSWORD = "demo12345";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const results = [];

function check(name, ok, extra = "") {
  results.push({ name, ok });
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${extra ? ` тАФ ${extra}` : ""}`);
  if (!ok) process.exitCode = 1;
}

async function waitForHttp(url, timeout = 30000) {
  const started = Date.now();
  while (Date.now() - started < timeout) {
    try {
      await fetch(url);
      return;
    } catch {
      await sleep(300);
    }
  }
  throw new Error(`service not reachable: ${url}`);
}

async function api(method, path, token, body) {
  const headers = {};
  if (body) headers["Content-Type"] = "application/json";
  if (token) headers.Authorization = `Bearer ${token}`;
  const response = await fetch(`${API}${path}`, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  return { status: response.status, data: text ? JSON.parse(text) : {} };
}

async function loginApi(email) {
  const { status, data } = await api("POST", "/auth/login/", null, {
    email,
    password: PASSWORD,
  });
  if (status !== 200) throw new Error(`login ${email}: ${status}`);
  return data.access;
}

function isoDate(offset) {
  const date = new Date();
  date.setDate(date.getDate() + offset);
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

async function newTarget() {
  const response = await fetch(
    `http://127.0.0.1:${CDP_PORT}/json/new?${encodeURIComponent("about:blank")}`,
    { method: "PUT" },
  );
  return response.json();
}

function connect(url) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(url);
    ws.addEventListener("open", () => resolve(ws), { once: true });
    ws.addEventListener("error", reject, { once: true });
  });
}

const HELPERS = `
  function fill(selector, value) {
    const input = document.querySelector(selector);
    if (!input) throw new Error('no input ' + selector);
    const proto = input instanceof HTMLSelectElement ? HTMLSelectElement.prototype : HTMLInputElement.prototype;
    const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
    setter.call(input, value);
    input.dispatchEvent(new Event(input instanceof HTMLSelectElement ? 'change' : 'input', { bubbles: true }));
    return input.value;
  }
  function byText(selector, text) {
    return [...document.querySelectorAll(selector)].find(
      (node) => node.textContent.trim() === text,
    );
  }
  function navTexts() {
    return JSON.stringify([...document.querySelectorAll('.site-header__link')].map((a) => a.textContent));
  }
  function recordCard(title) {
    return [...document.querySelectorAll('.record-card')].find(
      (card) => card.querySelector('.record-card__title')?.textContent.trim() === title,
    );
  }
  function queueGroup(title) {
    return [...document.querySelectorAll('.queue-group')].find(
      (group) => group.querySelector('.queue-group__title')?.textContent.trim() === title,
    );
  }
`;

async function main() {
  await waitForHttp(`http://127.0.0.1:${CDP_PORT}/json/version`);
  await waitForHttp(`${APP}/login`);
  await sleep(800);

  // --- ╨Я╨╛╨┤╨│╨╛╤В╨╛╨▓╨║╨░ ╤З╨╡╤А╨╡╨╖ API: ╨║╨╜╨╕╨│╨░ ╤Б ╨╛╨┤╨╜╨╕╨╝ ╤Н╨║╨╖╨╡╨╝╨┐╨╗╤П╤А╨╛╨╝, ╨╖╨░╨╜╤П╤В╤Л╨╝ reader2.
  const stamp = new Date().toISOString().slice(11, 19).replaceAll(":", "");
  const title = `E2E ╨╛╤З╨╡╤А╨╡╨┤╤М ${stamp}`;
  const adminToken = await loginApi("admin@library.local");
  const reader2Token = await loginApi("reader2@library.local");
  const reader3Token = await loginApi("reader3@library.local");

  const book = await api("POST", "/books/", adminToken, {
    title,
    author: "╨Я╤А╨╛╨▓╨╡╤А╨║╨░ ╨╕╨╜╤В╨╡╤А╤Д╨╡╨╣╤Б╨░",
    genre: "╨Я╤А╨╛╨▓╨╡╤А╨║╨░",
    year: 2026,
  });
  if (book.status !== 201) throw new Error(`create book: ${book.status}`);
  const bookId = book.data.id;

  const copy = await api("POST", `/books/${bookId}/copies/`, adminToken, {
    inventory_number: `E2E-${stamp}`,
    condition: "good",
  });
  if (copy.status !== 201) throw new Error(`create copy: ${copy.status}`);

  const loan = await api("POST", "/loans/", reader2Token, {
    copy_id: copy.data.id,
    start_date: isoDate(0),
    due_date: isoDate(5),
  });
  if (loan.status !== 201) throw new Error(`create loan: ${loan.status}`);

  const reservation = await api("POST", "/reservations/", reader3Token, {
    book_id: bookId,
  });
  if (reservation.status !== 201) throw new Error(`create reservation: ${reservation.status}`);
  console.log(`╨Я╨╛╨┤╨│╨╛╤В╨╛╨▓╨╗╨╡╨╜╨░ ╨║╨╜╨╕╨│╨░ ┬л${title}┬╗ (id ${bookId}), ╨▒╤А╨╛╨╜╤М reader2, ╨╛╤З╨╡╤А╨╡╨┤╤М reader3\n`);

  const target = await newTarget();
  const ws = await connect(target.webSocketDebuggerUrl);

  let lastId = 0;
  const pending = new Map();
  ws.addEventListener("message", (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) reject(new Error(JSON.stringify(message.error)));
      else resolve(message.result);
    }
  });

  function send(method, params = {}) {
    const id = ++lastId;
    ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
  }

  async function evalJs(expression) {
    const response = await send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true,
      userGesture: true,
    });
    if (response.exceptionDetails) {
      throw new Error(
        response.exceptionDetails.exception?.description || "evaluate failed",
      );
    }
    return response.result.value;
  }

  async function waitFor(expression, label, timeout = 20000) {
    const started = Date.now();
    while (Date.now() - started < timeout) {
      const value = await evalJs(expression).catch(() => false);
      if (value) return value;
      await sleep(150);
    }
    const body = await evalJs("document.body.innerText.slice(0, 600)").catch(() => "?");
    throw new Error(`timeout: ${label}; page: ${body}`);
  }

  async function navigate(url) {
    await send("Page.navigate", { url });
    await waitFor("document.readyState === 'complete'", `load ${url}`);
    await waitFor("document.getElementById('root')?.children.length > 0", `render ${url}`);
  }

  async function loginUi(email) {
    await navigate(`${APP}/login`);
    await evalJs(
      `${HELPERS}; fill('#login-email', ${JSON.stringify(email)}); fill('#login-password', '${PASSWORD}'); document.querySelector('form').requestSubmit();`,
    );
    await waitFor("location.pathname === '/catalog'", `login ${email}`, 25000);
  }

  async function logoutUi() {
    await evalJs("document.querySelector('.site-header__logout')?.click();");
    await waitFor("location.pathname === '/login'", "logout");
  }

  await send("Page.enable");
  await send("Runtime.enable");
  await send("Storage.clearDataForOrigin", {
    origin: APP,
    storageTypes: "local_storage",
  });

  // --- ╨з╨╕╤В╨░╤В╨╡╨╗╤М: ╨╜╨░╨▓╨╕╨│╨░╤Ж╨╕╤П ╨╕ ╨╖╨░╤Й╨╕╤В╨░ ╤А╨╛╨╗╨╡╨╣.
  await loginUi("reader3@library.local");
  const readerNav = await evalJs(`${HELPERS}; navTexts()`);
  check(
    "╨з╨╕╤В╨░╤В╨╡╨╗╤М ╨▓╨╕╨┤╨╕╤В ┬л╨Ь╨╛╨╕ ╨▒╤А╨╛╨╜╨╕┬╗ ╨╕ ┬л╨Ю╤З╨╡╤А╨╡╨┤╤М┬╗",
    readerNav.includes("╨Ь╨╛╨╕ ╨▒╤А╨╛╨╜╨╕") && readerNav.includes("╨Ю╤З╨╡╤А╨╡╨┤╤М"),
    readerNav,
