  check("╨з╨╕╤В╨░╤В╨╡╨╗╤М ╨╜╨╡ ╨▓╨╕╨┤╨╕╤В ┬л╨Т╤Л╨┤╨░╤З╨░┬╗", !readerNav.includes("╨Т╤Л╨┤╨░╤З╨░"), readerNav);

  await navigate(`${APP}/librarian`);
  await waitFor("location.pathname === '/catalog'", "reader blocked from librarian");
  check("╨з╨╕╤В╨░╤В╨╡╨╗╤П ╨╜╨╡ ╨┐╤Г╤Б╨║╨░╨╡╤В ╨▓ /librarian", true);

  // --- ╨Ю╤З╨╡╤А╨╡╨┤╤М ╤З╨╕╤В╨░╤В╨╡╨╗╤П: ╨╛╨╢╨╕╨┤╨░╨╜╨╕╨╡ ╨╜╨░ ╨║╨░╤А╤В╨╛╤З╨║╨╡ ╨╕ ╨▓ ╤Б╨┐╨╕╤Б╨║╨╡.
  await navigate(`${APP}/my/queue`);
  await waitFor("!!document.querySelector('.dashboard__title')", "queue page");
  const queueTitle = await evalJs("document.querySelector('.dashboard__title')?.textContent");
  check("╨н╨║╤А╨░╨╜ ┬л╨Ь╨╛╤П ╨╛╤З╨╡╤А╨╡╨┤╤М┬╗ ╨╛╤В╨║╤А╤Л╨▓╨░╨╡╤В╤Б╤П", queueTitle === "╨Ь╨╛╤П ╨╛╤З╨╡╤А╨╡╨┤╤М", queueTitle);

  await waitFor(
    `${HELPERS}; !!recordCard(${JSON.stringify(title)}) && !!recordCard(${JSON.stringify(title)}).querySelector('.status--waiting')`,
    "own waiting reservation",
  );
  const positionText = await evalJs(
    `${HELPERS}; recordCard(${JSON.stringify(title)})?.querySelector('.record-card__detail dd')?.textContent`,
  );
  check("╨Т ╨╛╤З╨╡╤А╨╡╨┤╨╕ ╨┐╨╛╨║╨░╨╖╨░╨╜╨░ ╨┐╨╛╨╖╨╕╤Ж╨╕╤П", positionText === "1", positionText);

  await navigate(`${APP}/books/${bookId}`);
