    "document.querySelector('.booking-panel__message--hold')?.textContent",
  );
  check(
    "╨Э╨░ ╤Б╤В╤А╨░╨╜╨╕╤Ж╨╡ ╨║╨╜╨╕╨│╨╕ ╨▓╨╕╨┤╨╜╨╛ ╨╛╨╢╨╕╨┤╨░╨╜╨╕╨╡ ╨▓ ╨╛╤З╨╡╤А╨╡╨┤╨╕",
    waitingText.includes("╨Т╤Л ╨▓ ╨╛╤З╨╡╤А╨╡╨┤╨╕") && waitingText.includes("╨Я╨╛╨╖╨╕╤Ж╨╕╤П: 1"),
    waitingText,
