  // --- ╨С╨╕╨▒╨╗╨╕╨╛╤В╨╡╨║╨░╤А╤М: ╨▓╤Л╨┤╨░╤З╨░ ╨╕ ╨▓╨╛╨╖╨▓╤А╨░╤В.
  await logoutUi();
  await loginUi("librarian1@library.local");
  const staffNav = await evalJs(`${HELPERS}; navTexts()`);
  check("╨С╨╕╨▒╨╗╨╕╨╛╤В╨╡╨║╨░╤А╤М ╨▓╨╕╨┤╨╕╤В ┬л╨Т╤Л╨┤╨░╤З╨░┬╗", staffNav.includes("╨Т╤Л╨┤╨░╤З╨░"), staffNav);
  check(
