  // --- ╨Ю╤З╨╡╤А╨╡╨┤╤М ╨▒╨╕╨▒╨╗╨╕╨╛╤В╨╡╨║╨░╤А╤П: ╤Г╨┤╨╡╤А╨╢╨░╨╜╨╕╨╡ ╨┐╨╛╤Б╨╗╨╡ ╨▓╨╛╨╖╨▓╤А╨░╤В╨░.
  await evalJs(`${HELPERS}; byText('.dashboard__tab', '╨Ю╤З╨╡╤А╨╡╨┤╤М')?.click();`);
